\echo 'Not touched: every table in the lapper schema.'
\if :apply
-- Only the listed tables, without CASCADE: a kept table that still references one of them
-- makes PostgreSQL refuse, and the whole transaction rolls back.
DO $clear_apply$
DECLARE list text; t text; n bigint; c record;
BEGIN
  SELECT string_agg(format('public.%I', tbl), ', ') INTO list FROM meshforge_clear_counts WHERE NOT keep;
